import{_ as n,a0 as d,w as p,s as o,I as i,x as a,a1 as t,A as l,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何清理你的 Ubuntu 14.10/14.04/13.10 系統 | LCTT x X-CMD","titleTemplate":false,"description":"如何清理你的 Ubuntu 14.10/14.04/13.10 系統 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何清理你的 Ubuntu 14.10/14.04/13.10 系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何清理你的 Ubuntu 14.10/14.04/13.10 系統 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150126 Cleaning up Ubuntu 14.10,14.04,13.10 system","title":"如何清理你的 Ubuntu 14.10/14.04/13.10 系統","tag":"201503","desc":""},"relativePath":"201503/20150126 Cleaning up Ubuntu 14.10,14.04,13.10 system.md","filePath":"[post].md"}'),h={name:"201503/20150126 Cleaning up Ubuntu 14.10,14.04,13.10 system.md"};function u(b,e,g,k,c,f){const s=d("Link");return p(),o("div",null,[e[19]||(e[19]=i("h1",{id:"如何清理你的-ubuntu-14-10-14-04-13-10-系統",tabindex:"-1"},[a("如何清理你的 Ubuntu 14.10/14.04/13.10 系統 "),i("a",{class:"header-anchor",href:"#如何清理你的-ubuntu-14-10-14-04-13-10-系統","aria-label":"Permalink to “如何清理你的 Ubuntu 14.10/14.04/13.10 系統”"},"​")],-1)),i("p",null,[e[1]||(e[1]=a("前面我們已經討論了",-1)),t(s,{href:"http://www.ubuntugeek.com/cleaning-up-all-unnecessary-junk-files-in-ubuntu.html"},{default:l(()=>[...e[0]||(e[0]=[a("如何清理 Ubuntu GNU/Linux 系統",-1)])]),_:1}),e[2]||(e[2]=a("，這篇教程將在原有教程的基礎上，增加對新的 Ubuntu 發行版本的支持，並介紹更多的工具。",-1))]),e[20]||(e[20]=r('<p>假如你想清理你的 Ubuntu 主機，你可以按照以下的一些簡單步驟來移除所有不需要的垃圾文件。</p><h2 id="移除多餘軟件包" tabindex="-1">移除多餘軟件包 <a class="header-anchor" href="#移除多餘軟件包" aria-label="Permalink to “移除多餘軟件包”">​</a></h2><p>這又是一個內置功能，但這次我們不必使用新得立包管理軟件(Synaptic Package Manager)，而是在終端中達到目的。</p><p>現在，在終端窗口中鍵入如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get autoclean</span></span></code></pre></div><p>這便激活了包清除命令。這個命令所做的工作是： 自動清除那些當你安裝或升級程序時系統所緩存的 <code>.deb</code> 包(即清除 <code>/var/cache/apt/archives</code> 目錄，不過只清理過時的包)。如果需要使用清除命令，只需在終端窗口中鍵入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get clean</span></span></code></pre></div><p>然後你就可以使用自動移除命令。這個命令所做的工作是：清除那些 在系統中被某個已經卸載的軟件 作為依賴所安裝的軟件包。要使用自動移除命令，在終端窗口中鍵入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get autoremove</span></span></code></pre></div><h2 id="移除不需要的本地化數據" tabindex="-1">移除不需要的本地化數據 <a class="header-anchor" href="#移除不需要的本地化數據" aria-label="Permalink to “移除不需要的本地化數據”">​</a></h2><p>為達到此目的，我們需要安裝 <code>localepurge</code> 軟件，它將自動移除一些不需要的本地化數據（LCTT 譯註：即各種語言翻譯）。這個軟件是一個簡單的腳本，它將從那些不再需要的本地化文件和本地化聯機手冊( man pages ) 所佔用的空間中回收磁盤空間。這個軟件將在任何 apt 安裝命令運行時 被自動激活。</p><p>在 Ubuntu 中安裝 <code>localepurge</code></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install localepurge</span></span></code></pre></div><p>在通過 <code>apt-get install</code> 安裝任意軟件後， localepurge 將移除所有不是使用你係統中所設定語言的翻譯文件和翻譯的聯機手冊。</p><p>假如你想設置 <code>localepurge</code>，你需要編輯 <code>/ect/locale.nopurge</code> 文件。</p><p>根據你已經安裝的軟件，這將為你節省幾兆的磁盤空間。</p><p>例子：-</p><p>假如我試着使用 <code>apt-get</code> 來安裝 <code>dicus</code>軟件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install discus</span></span></code></pre></div><p>在軟件安裝完畢之後，你將看到如下提示：</p><blockquote><p>localepurge: Disk space freed in /usr/share/locale: 41860K</p></blockquote><h2 id="移除孤包" tabindex="-1">移除孤包 <a class="header-anchor" href="#移除孤包" aria-label="Permalink to “移除孤包”">​</a></h2><p>假如你想移除孤包，你需要安裝 <code>deborphan</code> 軟件：</p><p>在 Ubuntu 中安裝 <code>deborphan</code> :</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install deborphan</span></span></code></pre></div><h3 id="使用-deborphan" tabindex="-1">使用 deborphan <a class="header-anchor" href="#使用-deborphan" aria-label="Permalink to “使用 deborphan”">​</a></h3><p>打開終端並鍵入如下命令即可:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo deborphan | xargs sudo apt-get -y remove --purge</span></span></code></pre></div><h3 id="使用-gtkorphan-來移除孤包" tabindex="-1">使用 GtkOrphan 來移除孤包 <a class="header-anchor" href="#使用-gtkorphan-來移除孤包" aria-label="Permalink to “使用 GtkOrphan 來移除孤包”">​</a></h3><p><code>GtkOrphan</code> (一個針對 debian 系發行版本的 Perl/Gtk2 應用) 是一個分析用户安裝過程狀態並查找孤立庫文件的圖形化工具，它為 <code>deborphan</code> 提供了一個 GUI 前端，並具備移除軟件包的功能。</p><h4 id="在-ubuntu-中安裝-gtkorphan" tabindex="-1">在 Ubuntu 中安裝 GtkOrphan <a class="header-anchor" href="#在-ubuntu-中安裝-gtkorphan" aria-label="Permalink to “在 Ubuntu 中安裝 GtkOrphan”">​</a></h4><p>打開終端並運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install gtkorphan</span></span></code></pre></div><h4 id="一張截圖" tabindex="-1">一張截圖 <a class="header-anchor" href="#一張截圖" aria-label="Permalink to “一張截圖”">​</a></h4><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2015/01/41.png" alt=""></p><h3 id="使用-wajig-移除孤包" tabindex="-1">使用 Wajig 移除孤包 <a class="header-anchor" href="#使用-wajig-移除孤包" aria-label="Permalink to “使用 Wajig 移除孤包”">​</a></h3><p><code>Wajig</code>是 Debian 包管理系統中一個簡單的軟件包管理前端。它將 apt、apt-cache、 dpkg、 /etc/init.d 中的腳本等 通過一個單一命令集成在一起，它的設計初衷是使用簡單和為它的所有功能提供豐富的文檔。</p><p>通過適當的 <code>sudo</code>配置，大多數（如果不是全部）的軟件包安裝和創建等任務可以通過一個用户 shell 來完成。<code>Wajig</code> 也適用於一般的系統管理。另外，一個 Gnome GUI 命令 <code>gjig</code>也被囊括在這個軟件包之中。</p><h4 id="在-ubuntu-中安裝-wajig" tabindex="-1">在 Ubuntu 中安裝 Wajig <a class="header-anchor" href="#在-ubuntu-中安裝-wajig" aria-label="Permalink to “在 Ubuntu 中安裝 Wajig”">​</a></h4><p>打開終端並運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install wajig</span></span></code></pre></div><h2 id="debfoster-跟蹤你在安裝過程中的操作" tabindex="-1">Debfoster --- 跟蹤你在安裝過程中的操作 <a class="header-anchor" href="#debfoster-跟蹤你在安裝過程中的操作" aria-label="Permalink to “Debfoster --- 跟蹤你在安裝過程中的操作”">​</a></h2><p>debfoster 將會維護一個列有被明確需要安裝的軟件包的列表，但不包括那些作為某個軟件的依賴而被安裝的軟件包。參數是完全可選的，你甚至可以使得在 dpkg 和/或 apt-get 每次運行之後馬上激活 debfoster 。</p><p>另外，你還可以在命令列中使用 debfoster 來安裝或移除某些特定的軟件包。那些後綴為 <code>---</code> 的軟件包將會被移除，而沒有後綴的軟件包將會被安裝。</p><p>假如一個新的軟件包或 debfoster 注意到作為某個軟件包的依賴的軟件包是一個孤包，則 debfoster 將會詢問你下一步如何操作。若你決定保留這個孤包， debfoster 將只會進行記錄並繼續安裝過程；若你覺得這個軟件包不足以引起你的興趣，在 debfoster 詢問這個問題後，它將移除這個軟件包。進一步的，如果你的決定使得其他的軟件包變為孤包，更多的提問將會接踵而來。</p><h3 id="在-ubuntu-中安裝-debfoster" tabindex="-1">在 Ubuntu 中安裝 debfoster <a class="header-anchor" href="#在-ubuntu-中安裝-debfoster" aria-label="Permalink to “在 Ubuntu 中安裝 debfoster”">​</a></h3><p>打開終端並運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install debfoster</span></span></code></pre></div><h3 id="使用-debfoster" tabindex="-1">使用 debfoster <a class="header-anchor" href="#使用-debfoster" aria-label="Permalink to “使用 debfoster”">​</a></h3><p>為了創建一個初始跟蹤文件，可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo debfoster -q</span></span></code></pre></div><p>你總可以編輯 <code>/var/lib/debfoster/keepers</code> 文件，來定義那些你想留在系統中的軟件包。</p><p>為了編輯這個文件，可以鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo vi /var/lib/debfoster/keepers</span></span></code></pre></div><p>要強制使 debfoster 去移除所有沒有被列在上面這個文件的軟件包，或安裝作為某些列在這個文件中的軟件包的依賴，它也同時會添加所有在這個列表中沒有被安裝的軟件包。若要根據這個列表來執行相關操作，只需執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo debfoster -f</span></span></code></pre></div><p>若需要跟蹤你新安裝的軟件包，你需要時不時地執行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo debfoster</span></span></code></pre></div><h2 id="xdiskusage-查看你的硬盤空間都去哪兒了" tabindex="-1">xdiskusage -- 查看你的硬盤空間都去哪兒了 <a class="header-anchor" href="#xdiskusage-查看你的硬盤空間都去哪兒了" aria-label="Permalink to “xdiskusage -- 查看你的硬盤空間都去哪兒了”">​</a></h2><p>圖形化地展示磁盤使用情況的 du。xdiskusage 是一個用户友好型的程序，它將為你展示你所有磁盤的使用情況。 它是在 Phillip C. Dykstra 所寫的 “xdu” 程序的基礎上設計的。做了一些修改以使得它可以為你運行 “du”命令，並顯示磁盤的剩餘空間，並且假如你想清晰地瞭解你的磁盤空間都去哪兒了，它還可以生成一個 PostScript 格式的名為 display.xdiskusage 的文件。</p><h3 id="在-ubuntu-中安裝-xdiskusage" tabindex="-1">在 Ubuntu 中安裝 xdiskusage <a class="header-anchor" href="#在-ubuntu-中安裝-xdiskusage" aria-label="Permalink to “在 Ubuntu 中安裝 xdiskusage”">​</a></h3><p>只需使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install xdiskusage</span></span></code></pre></div><p>若你想打開這個應用，你需要使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo xdiskusage</span></span></code></pre></div><p>一旦這個應用被打開，你將看到如下圖所示的界面：</p><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2015/01/5.png" alt=""></p><h2 id="bleachbit" tabindex="-1">Bleachbit <a class="header-anchor" href="#bleachbit" aria-label="Permalink to “Bleachbit”">​</a></h2><p>BleachBit 能快速地釋放磁盤空間並不知疲倦地保護你的隱私。它可以釋放緩存，刪除 cookie，清除 Internet 上網歷史，粉碎臨時文件，刪除日誌，丟棄你所不知道存在何處的垃圾。為 Linux 和 Windows 系統而設計，它支持擦除清理數以千計的應用程序，如 Firefox, Internet Explorer, Adobe Flash, Google Chrome, Opera, Safari 等等。除了簡單地刪除文件，BleachBit 還包括許多高級功能，諸如粉碎文件以防止恢復，擦除磁盤空間來隱藏被其他應用程序所刪除文件的痕跡，為火狐“除塵”，使其速度更快等。比免費更好，BleachBit 是一個開源軟件。</p><h3 id="在-ubuntu-中安裝-bleachbit" tabindex="-1">在 Ubuntu 中安裝 Bleachbit <a class="header-anchor" href="#在-ubuntu-中安裝-bleachbit" aria-label="Permalink to “在 Ubuntu 中安裝 Bleachbit”">​</a></h3><p>打開終端並運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install bleachbit</span></span></code></pre></div><h3 id="一張截圖-1" tabindex="-1">一張截圖 <a class="header-anchor" href="#一張截圖-1" aria-label="Permalink to “一張截圖”">​</a></h3><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2015/01/6.png" alt=""></p><h3 id="使用-ubuntu-tweak" tabindex="-1">使用 Ubuntu-Tweak <a class="header-anchor" href="#使用-ubuntu-tweak" aria-label="Permalink to “使用 Ubuntu-Tweak”">​</a></h3>',75)),i("p",null,[e[4]||(e[4]=a("最後，你也可以使用 ",-1)),t(s,{href:"http://linux.cn/article-3335-1.html"},{default:l(()=>[...e[3]||(e[3]=[a("Ubuntu-Tweak",-1)])]),_:1}),e[5]||(e[5]=a(" 來清理你的系統。",-1))]),e[21]||(e[21]=i("hr",null,null,-1)),i("p",null,[e[7]||(e[7]=a("via: ",-1)),t(s,{href:"http://www.ubuntugeek.com/cleaning-up-a-ubuntu-gnulinux-system-updated-with-ubuntu-14-10-and-more-tools-added.html"},{default:l(()=>[...e[6]||(e[6]=[a("http://www.ubuntugeek.com/cleaning-up-a-ubuntu-gnulinux-system-updated-with-ubuntu-14-10-and-more-tools-added.html",-1)])]),_:1})]),i("p",null,[e[11]||(e[11]=a("作者：",-1)),t(s,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:l(()=>[...e[8]||(e[8]=[a("ruchi",-1)])]),_:1}),e[12]||(e[12]=a(" 譯者：",-1)),t(s,{href:"https://github.com/FSSlc"},{default:l(()=>[...e[9]||(e[9]=[a("FSSlc",-1)])]),_:1}),e[13]||(e[13]=a(" 校對：",-1)),t(s,{href:"https://github.com/wxy"},{default:l(()=>[...e[10]||(e[10]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[16]||(e[16]=a("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[14]||(e[14]=[a("LCTT",-1)])]),_:1}),e[17]||(e[17]=a(" 原創翻譯，",-1)),t(s,{href:"http://linux.cn/"},{default:l(()=>[...e[15]||(e[15]=[a("Linux中國",-1)])]),_:1}),e[18]||(e[18]=a(" 榮譽推出",-1))])])}const C=n(h,[["render",u]]);export{y as __pageData,C as default};
